// Generates supabase/seed.sql from src/lib/defaults.ts and src/lib/seedData.ts.
// Run with `npm run gen:seed`.
import { writeFileSync } from 'node:fs'
import { DEFAULT_SETTINGS } from '../src/lib/defaults.ts'
import { SEED_BOOKINGS, SEED_HOLIDAYS } from '../src/lib/seedData.ts'
import { PUBLIC_SETTING_KEYS } from '../src/lib/types.ts'

const q = (s: string | null | undefined) => (s == null ? 'null' : `'${s.replace(/'/g, "''")}'`)

const lines: string[] = [
  '-- Generated by scripts/gen-seed.ts. Do not edit by hand.',
  '-- Run once after the migrations.',
  '',
  '-- Settings',
]

for (const [key, value] of Object.entries(DEFAULT_SETTINGS)) {
  const isPublic = PUBLIC_SETTING_KEYS.includes(key as never)
  lines.push(
    `insert into public.settings (key, value, is_public) values (${q(key)}, ${q(JSON.stringify(value))}::jsonb, ${isPublic}) on conflict (key) do nothing;`,
  )
}

lines.push('', '-- Holidays (fixed dates only, add Raya, CNY, Deepavali and school holidays in the admin)')
for (const h of SEED_HOLIDAYS) {
  lines.push(
    `insert into public.holidays (date, name, kind) values (${q(h.date)}, ${q(h.name)}, ${q(h.kind)}) on conflict (date) do nothing;`,
  )
}

lines.push('', '-- Existing bookings as at 1 Nov 2026 (confirm price and status in the admin)')
for (const b of SEED_BOOKINGS) {
  lines.push(
    `insert into public.bookings (guest_name, origin, check_in, check_out, status, notes, total_price) values (${q(b.guest_name)}, ${q(b.origin)}, ${q(b.check_in)}, ${q(b.check_out)}, ${q(b.status)}, ${q(b.notes)}, 0);`,
  )
}

writeFileSync(new URL('../supabase/seed.sql', import.meta.url), lines.join('\n') + '\n')
console.log('supabase/seed.sql written')
